    ('c032e692-bf5f-5cdf-b5d0-08dc06fd5d2a'::uuid, 'Quiz — Rechercher, trier, agréger', 'NSI', '1re', 'Algorithmes sur les tableaux', 'b81df373-64b5-5b25-8675-f3fc0e542e6b'::uuid),
    ('bd3a9a63-638d-523f-a805-c4444923a696'::uuid, 'Quiz — Des données en table, et ce qu’on en tire', 'NSI', '1re', 'Traitement de tables matricielles (tableur)', 'd51d146b-bd01-5531-9f72-21e04c0dde8a'::uuid),
    ('059222c8-068f-5042-ab33-c4cf85a83348'::uuid, 'Quiz — Le meilleur choix immédiat, et ses limites', 'NSI', '1re', 'Algorithmes gloutons', '0af13a0f-50ca-5a02-88ad-d0f01c984afd'::uuid),
    ('29426197-2e10-50e5-9964-033fff22ebe0'::uuid, 'Quiz — Apprendre à partir de données', 'NSI', '1re', 'Algorithmes d’apprentissage', '990d19f2-f6aa-5379-93ec-205d01d1d811'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('5ea0cd29-7b84-53a1-8405-75f470313357'::uuid, '5fa230cc-1d73-526f-bde5-6b93c0823003'::uuid, 'Que signifie le mot « bit » ?', 'mcq', '["Binary digit, l’unité d’information à deux états","Byte information transfer","Un octet","Une unité de vitesse"]'::jsonb, 0, 'Il ne prend que deux valeurs : 0 ou 1.', 1),
    ('c4526d94-c67a-5304-b31e-07eaa02e6c22'::uuid, '5fa230cc-1d73-526f-bde5-6b93c0823003'::uuid, 'Pourquoi les ordinateurs utilisent-ils le binaire ?', 'mcq', '["Parce qu’un circuit distingue de façon fiable deux états, pas dix","Parce que c’est plus rapide à calculer","Parce que les mathématiques l’imposent","Parce que cela économise de l’énergie"]'::jsonb, 0, 'C’est une conséquence de la fiabilité physique du signal.', 2),
    ('b17696c1-8f08-5cca-a829-39138ede36df'::uuid, '5fa230cc-1d73-526f-bde5-6b93c0823003'::uuid, 'Que vaut le nombre binaire 1101 en décimal ?', 'mcq', '["13","11","14","9"]'::jsonb, 0, '8 + 4 + 0 + 1 = 13.', 3),
    ('57374959-86c4-58eb-9da3-2902773ac7c1'::uuid, '5fa230cc-1d73-526f-bde5-6b93c0823003'::uuid, 'Combien de valeurs peut-on coder sur n bits ?', 'mcq', '["2 puissance n","n puissance 2","2 × n","n / 2"]'::jsonb, 0, 'Ajouter un seul bit double le nombre de valeurs représentables.', 4),
    ('643bf593-b1bd-5ab6-a85b-feff5240d91d'::uuid, '5fa230cc-1d73-526f-bde5-6b93c0823003'::uuid, 'Huit bits suffisent à coder 300 valeurs différentes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Huit bits n’en codent que 256 : il en faut neuf.', 5),
    ('ac3c1c5a-53d1-50b5-aa19-75bf0ad777c5'::uuid, '5fa230cc-1d73-526f-bde5-6b93c0823003'::uuid, 'Comment convertit-on un nombre décimal en binaire ?', 'mcq', '["Par divisions successives par 2, restes lus de bas en haut","Par multiplications par 2","Par divisions par 10","En additionnant les chiffres"]'::jsonb, 0, 'L’ordre de lecture des restes est le piège habituel.', 6),
    ('0e3ed7c7-2e0d-59ae-a1ca-0b8794df4c2d'::uuid, '5fa230cc-1d73-526f-bde5-6b93c0823003'::uuid, 'Combien vaut 1 + 1 en binaire ?', 'mcq', '["10","2","11","0"]'::jsonb, 0, 'Zéro et je retiens un : la retenue est le mécanisme de base de l’addition.', 7),
    ('ec2ec028-ca3a-5f8e-8d3a-c75da6f8f3dc'::uuid, '5fa230cc-1d73-526f-bde5-6b93c0823003'::uuid, 'Un même mot binaire peut représenter un entier, une lettre ou une couleur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Seule la convention du programme décide de son interprétation.', 8),
    ('0dc74b9e-5363-5f5d-bc57-308f9dbe3bb1'::uuid, '33f0743e-6da3-5372-aaf1-738b22dd7feb'::uuid, 'Combien de valeurs un octet peut-il coder ?', 'mcq', '["256","8","128","1 024"]'::jsonb, 0, 'De 0 à 255 : 2 puissance 8.', 1),
    ('c56a3e3b-24fb-52c4-be55-ddd85d049c1f'::uuid, '33f0743e-6da3-5372-aaf1-738b22dd7feb'::uuid, 'Combien de bits vaut un chiffre hexadécimal ?', 'mcq', '["Quatre","Huit","Deux","Seize"]'::jsonb, 0, 'Deux chiffres hexadécimaux suffisent donc à écrire un octet.', 2),
    ('f7e3bedc-7fd2-5ff0-9b9c-632b8b112a0c'::uuid, '33f0743e-6da3-5372-aaf1-738b22dd7feb'::uuid, 'Un kibioctet vaut 1 000 octets.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il vaut 1 024 octets ; c’est le kilooctet qui en vaut 1 000.', 3),
    ('9cfde24b-b482-54ab-8f1f-59c00be645f8'::uuid, '33f0743e-6da3-5372-aaf1-738b22dd7feb'::uuid, 'Que signifie un débit annoncé en Mb/s plutôt qu’en Mo/s ?', 'mcq', '["Il est huit fois plus petit, car b désigne le bit","Il est huit fois plus grand","C’est identique","Cela dépend du fournisseur"]'::jsonb, 0, 'b minuscule pour bit, B majuscule pour octet.', 4),
    ('027b021e-aba4-57c7-a70b-1f1dbe2e07ee'::uuid, '33f0743e-6da3-5372-aaf1-738b22dd7feb'::uuid, 'Sur combien d’octets UTF-8 encode-t-il un caractère ?', 'mcq', '["De un à quatre selon le caractère","Toujours un","Toujours deux","Toujours quatre"]'::jsonb, 0, 'Les caractères ASCII y tiennent toujours sur un seul octet.', 5),
    ('b41ae009-33cf-5a7a-a725-c6f455cc047c'::uuid, '33f0743e-6da3-5372-aaf1-738b22dd7feb'::uuid, 'Quel est le poids brut d’une image de 1 000 par 1 000 pixels en couleurs vraies ?', 'mcq', '["Environ 3 millions d’octets","Environ 1 million d’octets","Environ 1 000 octets","Environ 24 octets"]'::jsonb, 0, 'Trois octets par pixel, avant toute compression.', 6),
    ('75aa472c-60f6-58b9-9552-755cc403e84b'::uuid, '33f0743e-6da3-5372-aaf1-738b22dd7feb'::uuid, 'Des caractères parasites à la place des accents signalent un octet corrompu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’octet est intact : c’est l’ENCODAGE de lecture qui est faux.', 7),
    ('f4016277-b545-59c3-a95f-8e90157c600f'::uuid, '33f0743e-6da3-5372-aaf1-738b22dd7feb'::uuid, 'Que représente le code couleur hexadécimal #FF8000 ?', 'mcq', '["Rouge à 255, vert à 128, bleu à 0","Rouge à 0, vert à 128, bleu à 255","Une couleur grise","Une transparence"]'::jsonb, 0, 'Deux chiffres hexadécimaux par composante.', 8),
    ('0a52e986-10bd-53fd-970f-9da1d58a1e5a'::uuid, '96f47a22-7d2d-5c00-8a00-049bcf16261d'::uuid, 'Qu’est-ce qu’un transistor, dans un processeur ?', 'mcq', '["Un interrupteur commandé électriquement","Une mémoire permanente","Un amplificateur de son","Une horloge"]'::jsonb, 0, 'Un processeur moderne en contient plusieurs milliards.', 1),
    ('7dd48c4f-d068-5a58-9b73-8bff9bd50173'::uuid, '96f47a22-7d2d-5c00-8a00-049bcf16261d'::uuid, 'Quelles sont les quatre parties de l’architecture de von Neumann ?', 'mcq', '["Unité de calcul, unité de commande, mémoire, entrées-sorties","Processeur, écran, clavier, disque","Cache, registre, mémoire vive, disque","Logiciel, système, pilote, matériel"]'::jsonb, 0, 'C’est le modèle de presque toutes les machines actuelles.', 2),
    ('ce64357a-15cb-54e6-be67-8cf43eb3ea46'::uuid, '96f47a22-7d2d-5c00-8a00-049bcf16261d'::uuid, 'Dans l’architecture de von Neumann, programme et données partagent la même mémoire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui permet à une machine de charger et d’exécuter n’importe quel programme.', 3),
    ('9ed0f288-eebc-5d13-9e03-943b56acc24f'::uuid, '96f47a22-7d2d-5c00-8a00-049bcf16261d'::uuid, 'Quelles sont les trois étapes du cycle d’exécution d’une instruction ?', 'mcq', '["Charger, décoder, exécuter","Lire, écrire, effacer","Compiler, lier, lancer","Saisir, calculer, afficher"]'::jsonb, 0, 'Le processeur les répète indéfiniment, au rythme de l’horloge.', 4),
    ('f61e9ec4-4b84-5b0c-b281-4e94a9960eaf'::uuid, '96f47a22-7d2d-5c00-8a00-049bcf16261d'::uuid, 'Quel composant garde un bit en mémoire dans un circuit logique ?', 'mcq', '["La bascule","L’additionneur","Le multiplexeur","Le comparateur"]'::jsonb, 0, 'C’est le passage du circuit qui calcule au circuit qui se souvient.', 5),
    ('8c26e1ee-7b1c-5a9e-b77e-63036d70261a'::uuid, '96f47a22-7d2d-5c00-8a00-049bcf16261d'::uuid, 'La mémoire vive conserve son contenu quand la machine est éteinte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est VOLATILE ; seul le stockage est persistant.', 6),
    ('476bed97-e3e2-5c10-bd17-c3b946924fb6'::uuid, '96f47a22-7d2d-5c00-8a00-049bcf16261d'::uuid, 'Comment sont classées les mémoires dans la hiérarchie ?', 'mcq', '["De la plus rapide et petite aux plus lentes et grandes","Par ordre alphabétique","De la plus grande à la plus petite capacité seulement","Par date de fabrication"]'::jsonb, 0, 'Registres, cache, mémoire vive, stockage.', 7),
    ('94d81c22-6302-5436-b72a-ce7852594772'::uuid, '96f47a22-7d2d-5c00-8a00-049bcf16261d'::uuid, 'Que mesure la fréquence d’horloge d’un processeur ?', 'mcq', '["Le nombre de cycles par seconde","Le nombre d’instructions par programme","La taille de la mémoire","La vitesse du réseau"]'::jsonb, 0, 'Trois milliards de cycles par seconde à 3 GHz.', 8),
    ('3a7fe9d7-12ea-5d8a-85bf-bc8a449787aa'::uuid, 'dec70b29-4d30-55ec-a57f-7fe5e033341d'::uuid, 'Quelle est la différence entre compilation et interprétation ?', 'mcq', '["La compilation traduit tout le programme avant l’exécution, l’interprétation ligne à ligne","La compilation est plus lente à l’exécution","L’interprétation produit un exécutable","Il n’y a aucune différence"]'::jsonb, 0, 'Python est interprété, ce qui décale la découverte des erreurs.', 1),
    ('ec8783e8-49a9-5d91-8d74-a9bfaa5fb7e5'::uuid, 'dec70b29-4d30-55ec-a57f-7fe5e033341d'::uuid, 'Qu’est-ce que l’assembleur ?', 'mcq', '["La traduction lisible du langage machine","Un langage de haut niveau","Un système d’exploitation","Un compilateur"]'::jsonb, 0, 'Chaque instruction machine y correspond à un mot mnémonique.', 2),
    ('bab48dd5-5800-58eb-8abc-12542f97a092'::uuid, 'dec70b29-4d30-55ec-a57f-7fe5e033341d'::uuid, 'En machine, 0,1 + 0,2 donne exactement 0,3.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '0,1 n’a pas d’écriture binaire finie : les flottants sont approchés.', 3),
    ('25270e6e-9b71-564a-bda8-c74cb5c639a0'::uuid, 'dec70b29-4d30-55ec-a57f-7fe5e033341d'::uuid, 'Comment comparer deux flottants de façon fiable ?', 'mcq', '["En testant si leur écart est inférieur à une tolérance","Avec un test d’égalité stricte","En les convertissant en chaînes","En les arrondissant à l’entier"]'::jsonb, 0, 'L’égalité stricte entre flottants est une source classique de bugs.', 4),
    ('c9228685-249a-520a-87bc-81c8091bd391'::uuid, 'dec70b29-4d30-55ec-a57f-7fe5e033341d'::uuid, 'Un programme peut-il déterminer si un autre programme s’arrêtera ?', 'mcq', '["Non, pas dans le cas général","Oui, toujours","Oui, s’il est assez rapide","Oui, depuis les processeurs modernes"]'::jsonb, 0, 'C’est le problème de l’arrêt : un résultat d’indécidabilité, non une limite technique.', 5),
    ('bd992fea-76ff-5c2a-83b8-c2744f7dd0a6'::uuid, 'dec70b29-4d30-55ec-a57f-7fe5e033341d'::uuid, 'Un programme compilé détecte les erreurs de syntaxe avant son lancement.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un programme interprété, lui, s’arrête au moment où il atteint la ligne fautive.', 6),
    ('220b5b28-9dc1-5b27-b25a-9189255a6444'::uuid, 'dec70b29-4d30-55ec-a57f-7fe5e033341d'::uuid, 'Qu’est-ce qu’un jeu d’instructions ?', 'mcq', '["L’ensemble des instructions élémentaires qu’une famille de processeurs sait exécuter","La liste des programmes installés","Le manuel d’un langage","Les fonctions d’une bibliothèque"]'::jsonb, 0, 'Il diffère d’une architecture de processeur à l’autre.', 7),
    ('570a38ef-30cd-5a6f-874e-7c678df305f5'::uuid, 'dec70b29-4d30-55ec-a57f-7fe5e033341d'::uuid, 'Quelles sont les trois grandes structures de contrôle d’un programme ?', 'mcq', '["Le test conditionnel, la boucle bornée et la boucle non bornée","La variable, la fonction et le type","L’entrée, le calcul et la sortie","Le module, la classe et l’objet"]'::jsonb, 0, 'Elles suffisent à exprimer tout algorithme.', 8),
    ('5ada29c9-db68-52bd-99fc-bc414cb04347'::uuid, 'e929ce03-9ac0-553e-946d-1c19263c3388'::uuid, 'Quel composant du système décide quel programme s’exécute et quand ?', 'mcq', '["L’ordonnanceur","Le compilateur","Le pilote","Le système de fichiers"]'::jsonb, 0, 'Il donne à chacun de courtes tranches de temps processeur.', 1),
    ('be506200-1afc-5bff-870b-2e4f044b6f39'::uuid, 'e929ce03-9ac0-553e-946d-1c19263c3388'::uuid, 'Qu’est-ce qu’un appel système ?', 'mcq', '["Une demande de service adressée par une application au noyau","Le démarrage de la machine","Un message d’erreur","Une commande du terminal"]'::jsonb, 0, 'C’est la seule voie par laquelle une application atteint le matériel.', 2),
    ('739a3aea-510c-5619-8885-e8d9eb4a013e'::uuid, 'e929ce03-9ac0-553e-946d-1c19263c3388'::uuid, 'Le cloisonnement de la mémoire empêche un programme qui plante d’emporter toute la machine.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Chaque processus est confiné dans son propre espace mémoire.', 3),
    ('47ca3dbb-5415-5c24-8ded-52bce2f6cb56'::uuid, 'e929ce03-9ac0-553e-946d-1c19263c3388'::uuid, 'À quoi sert un pilote (driver) ?', 'mcq', '["À traduire les demandes générales du système en commandes propres à un matériel","À accélérer le processeur","À compiler les programmes","À gérer les mots de passe"]'::jsonb, 0, 'Sans lui, chaque logiciel devrait connaître chaque modèle de composant.', 4),
    ('814e3df0-88ed-5652-80e5-7340fa843836'::uuid, 'e929ce03-9ac0-553e-946d-1c19263c3388'::uuid, 'Que change le renommage d’une image en fichier .txt ?', 'mcq', '["Rien à son contenu : l’extension n’est qu’une convention de nom","Le fichier devient du texte","Le fichier est détruit","Le fichier est compressé"]'::jsonb, 0, 'Le système s’en sert seulement pour choisir l’application d’ouverture.', 5),
    ('3e12ab4d-bac7-5c0c-8864-07fa04c4d097'::uuid, 'e929ce03-9ac0-553e-946d-1c19263c3388'::uuid, 'Un logiciel libre est nécessairement gratuit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La liberté porte sur l’usage, l’étude, la modification et la redistribution, pas sur le prix.', 6),
    ('7d9fb145-4c0d-54a3-962d-2265fe92b835'::uuid, 'e929ce03-9ac0-553e-946d-1c19263c3388'::uuid, 'Qu’est-ce qu’un chemin absolu ?', 'mcq', '["Un chemin qui part de la racine de l’arborescence","Un chemin qui part du répertoire courant","Le nom du fichier seul","L’adresse d’un serveur"]'::jsonb, 0, 'Le chemin relatif, lui, dépend d’où l’on se trouve.', 7),
    ('ff57b5d6-04cb-5af1-a4fb-b97270d4bbff'::uuid, 'e929ce03-9ac0-553e-946d-1c19263c3388'::uuid, 'Quelle est la différence entre mode utilisateur et mode noyau ?', 'mcq', '["Le mode noyau a tous les droits sur le matériel, le mode utilisateur est restreint","Le mode noyau est réservé à l’administrateur humain","Le mode utilisateur est plus rapide","Il n’y a pas de différence technique"]'::jsonb, 0, 'Cette frontière fait la sécurité de tout le système.', 8),
    ('4766f82e-aaea-5d02-8912-a2a773396dc4'::uuid, 'd9b7b6d8-d4e5-551f-88de-7224247c29c2'::uuid, 'Dans quelle catégorie ranger un écran tactile ?', 'mcq', '["Entrée-sortie","Entrée seulement","Sortie seulement","Stockage"]'::jsonb, 0, 'Il affiche et il capte le toucher.', 1),
    ('1d2361ad-cd8e-57e0-9b49-69a1245ea627'::uuid, 'd9b7b6d8-d4e5-551f-88de-7224247c29c2'::uuid, 'Quel avantage principal un SSD a-t-il sur un disque dur ?', 'mcq', '["Un accès bien plus rapide, sans pièce mobile","Une capacité toujours supérieure","Un coût plus faible au téraoctet","Un nombre illimité d’écritures"]'::jsonb, 0, 'Il est en revanche plus cher et ses cellules ont une usure à l’écriture.', 2),
    ('18b5f2e1-6d0c-54ec-9a19-553971ffb97f'::uuid, 'd9b7b6d8-d4e5-551f-88de-7224247c29c2'::uuid, 'Le contenu d’un SSD disparaît quand la machine est éteinte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le stockage est persistant ; c’est la mémoire vive qui est volatile.', 3),
    ('2cdfe218-c1c9-5b41-9d61-66d96b2c206c'::uuid, 'd9b7b6d8-d4e5-551f-88de-7224247c29c2'::uuid, 'Qu’est-ce qu’une interruption ?', 'mcq', '["Un signal par lequel un périphérique demande l’attention du processeur","Un arrêt du système","Une erreur de programme","Une coupure de courant"]'::jsonb, 0, 'Elle évite au processeur de surveiller en permanence chaque périphérique.', 4),
    ('9bc21d60-7c2f-55a0-8544-9f27d23bc7ca'::uuid, 'd9b7b6d8-d4e5-551f-88de-7224247c29c2'::uuid, 'Quelle méthode consiste à vérifier périodiquement l’état d’un périphérique ?', 'mcq', '["La scrutation","L’interruption","La compilation","L’ordonnancement"]'::jsonb, 0, 'Simple, mais coûteuse en temps de calcul.', 5),
    ('3135dd2e-dbe0-5206-8853-8f7b4eed75f6'::uuid, 'd9b7b6d8-d4e5-551f-88de-7224247c29c2'::uuid, 'Le débit réel d’une interface est toujours inférieur à son débit théorique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’encodage et les contrôles d’erreur consomment une part du canal.', 6),
    ('17d26c27-575f-5576-b472-88d76dd2d90d'::uuid, 'd9b7b6d8-d4e5-551f-88de-7224247c29c2'::uuid, 'Comment une application accède-t-elle à une imprimante ?', 'mcq', '["En demandant le service au système, qui passe par le pilote","En pilotant directement le matériel","En écrivant sur le disque","En envoyant une interruption"]'::jsonb, 0, 'Le logiciel n’a pas à connaître le modèle d’imprimante.', 7),
    ('8e5319b0-ebd1-5c43-82a8-b6166dd3b244'::uuid, 'd9b7b6d8-d4e5-551f-88de-7224247c29c2'::uuid, 'Qu’est-ce qu’un bus, pour un périphérique ?', 'mcq', '["La liaison, physique ou sans fil, définie par un débit et un protocole","Un composant de la carte mère uniquement","Le pilote du périphérique","Un type de mémoire"]'::jsonb, 0, 'USB, HDMI, Bluetooth et Wi-Fi en sont des exemples.', 8),
    ('23b901d4-a960-5d2e-bc76-e64bc90a523e'::uuid, '571eec87-732c-5547-8fdd-5e4188e3972c'::uuid, 'Quelle différence entre adresse MAC et adresse IP ?', 'mcq', '["La MAC est physique et fixe, l’IP est logique et attribuée par le réseau","La MAC change à chaque connexion","L’IP est gravée dans la carte réseau","Elles sont interchangeables"]'::jsonb, 0, 'La MAC sert dans le réseau local, l’IP à l’échelle mondiale.', 1),
    ('dc4897dd-b67f-5cfc-bbd2-e659e6adfa64'::uuid, '571eec87-732c-5547-8fdd-5e4188e3972c'::uuid, 'À quoi sert le masque de sous-réseau ?', 'mcq', '["À savoir si le destinataire est sur le même réseau","À chiffrer les données","À compter les machines connectées","À accélérer la transmission"]'::jsonb, 0, 'Il sépare la partie réseau de la partie machine dans l’adresse IP.', 2),
    ('31628e15-01a0-51f4-bb8c-1e0a727bdc56'::uuid, '571eec87-732c-5547-8fdd-5e4188e3972c'::uuid, 'Le protocole IP garantit que les paquets arrivent dans l’ordre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'IP est sans connexion et sans garantie : c’est TCP qui apporte l’ordre.', 3),
    ('1a91c53b-cf2c-50ad-94aa-fb6d05b3cde8'::uuid, '571eec87-732c-5547-8fdd-5e4188e3972c'::uuid, 'À quoi sert le champ TTL d’un paquet ?', 'mcq', '["À détruire un paquet qui a traversé trop de routeurs","À mesurer le débit","À chiffrer l’en-tête","À identifier l’expéditeur"]'::jsonb, 0, 'Il empêche un paquet mal routé de tourner indéfiniment.', 4),
    ('2b1365d2-5e8d-5abb-aaad-127b934b177a'::uuid, '571eec87-732c-5547-8fdd-5e4188e3972c'::uuid, 'Comment un routeur choisit-il où envoyer un paquet ?', 'mcq', '["Il consulte sa table de routage et choisit le prochain saut","Il connaît tout le trajet à l’avance","Il demande à l’expéditeur","Il diffuse le paquet à tout le réseau"]'::jsonb, 0, 'Le routage se fait de proche en proche.', 5),
    ('dfca42e2-55ea-51dd-aaaf-b7743a9bd6a3'::uuid, '571eec87-732c-5547-8fdd-5e4188e3972c'::uuid, 'Sur combien d’octets s’écrit une adresse IPv4 ?', 'mcq', '["Quatre","Six","Seize","Huit"]'::jsonb, 0, 'Soit environ 4 milliards d’adresses, épuisées depuis des années.', 6),
    ('eba7be1c-299b-57c5-9e00-65fd5f11439a'::uuid, '571eec87-732c-5547-8fdd-5e4188e3972c'::uuid, 'Que fait un serveur DNS ?', 'mcq', '["Il traduit un nom de domaine en adresse IP","Il attribue les adresses MAC","Il route les paquets","Il chiffre les communications"]'::jsonb, 0, 'Sans lui, il faudrait retenir des suites de chiffres.', 7),
    ('2424c06f-1d71-557f-8349-2be4f06a82e0'::uuid, '571eec87-732c-5547-8fdd-5e4188e3972c'::uuid, 'Deux paquets d’un même échange peuvent emprunter des chemins différents.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Chaque routeur décide indépendamment : l’ordre d’arrivée n’est pas garanti.', 8),
    ('d63e7297-d3e8-5bb7-8696-ea545f2520e7'::uuid, 'fed6e900-df7c-5c89-81d6-1d7f52b7eefc'::uuid, 'Que se passe-t-il si l’émetteur ne reçoit pas d’accusé de réception ?', 'mcq', '["Il retransmet le message après un délai de garde","Il abandonne l’envoi","Il passe au message suivant","Il ferme la connexion"]'::jsonb, 0, 'C’est le mécanisme de base de la fiabilité.', 1),
    ('724fb885-fc45-53e1-a200-d43dfe878739'::uuid, 'fed6e900-df7c-5c89-81d6-1d7f52b7eefc'::uuid, 'Quel problème le protocole du bit alterné résout-il ?', 'mcq', '["Le doublon créé par la retransmission quand un accusé s’est perdu","La lenteur du réseau","Le chiffrement des données","Le routage des paquets"]'::jsonb, 0, 'Sans numéro, le récepteur compterait deux fois le même message.', 2),
    ('f28fc96c-3fa8-554f-9e43-bb693b416b0a'::uuid, 'fed6e900-df7c-5c89-81d6-1d7f52b7eefc'::uuid, 'Pourquoi un seul bit suffit-il dans le protocole du bit alterné ?', 'mcq', '["Parce que l’émetteur n’envoie qu’un message à la fois et attend son acquittement","Parce que les messages sont très courts","Parce que le réseau est fiable","Parce que le récepteur mémorise tout"]'::jsonb, 0, 'Il ne peut jamais y avoir plus de deux messages en jeu.', 3),
    ('212dbe38-64bf-5833-851c-18d5a7b3637d'::uuid, 'fed6e900-df7c-5c89-81d6-1d7f52b7eefc'::uuid, 'Que fait le récepteur s’il reçoit un message portant le numéro précédent ?', 'mcq', '["Il jette le doublon et réacquitte","Il l’enregistre une seconde fois","Il ferme la connexion","Il l’ignore sans répondre"]'::jsonb, 0, 'Son accusé précédent s’était perdu : il faut le renvoyer.', 4),
    ('6ac6ba8b-5e4d-58bb-b3dd-cce990839f6b'::uuid, 'fed6e900-df7c-5c89-81d6-1d7f52b7eefc'::uuid, 'TCP permet d’avoir plusieurs messages en vol simultanément.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le mécanisme de fenêtre, qui généralise le bit alterné.', 5),
    ('14e9cfde-fba6-5362-b738-67c171592e02'::uuid, 'fed6e900-df7c-5c89-81d6-1d7f52b7eefc'::uuid, 'Que garantit TCP que IP ne garantit pas ?', 'mcq', '["La fiabilité, l’ordre et l’absence de doublon","L’adressage des machines","Le routage des paquets","Le chiffrement"]'::jsonb, 0, 'IP se contente de faire de son mieux.', 6),
    ('377b7556-f109-5670-bc01-5fcbffb2d0ee'::uuid, 'fed6e900-df7c-5c89-81d6-1d7f52b7eefc'::uuid, 'Pourquoi préfère-t-on UDP pour la vidéo en direct ?', 'mcq', '["Un paquet retransmis arriverait trop tard pour être joué","UDP est plus fiable","UDP chiffre les données","UDP garantit l’ordre"]'::jsonb, 0, 'La latence y prime sur l’exhaustivité.', 7),
    ('c0c9dd4e-2ae2-56f3-83ba-a259982a765f'::uuid, 'fed6e900-df7c-5c89-81d6-1d7f52b7eefc'::uuid, 'Le contrôle de congestion de TCP réduit le débit quand le réseau sature.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le contrôle de flux, lui, protège un récepteur trop lent.', 8),
    ('a81ac8ad-6e37-5d07-831d-166b825dddd9'::uuid, '4e6885ca-c814-5e95-bcd3-7d3068cc5f88'::uuid, 'Dans le modèle client-serveur, qui prend l’initiative de l’échange ?', 'mcq', '["Le client","Le serveur","Les deux indifféremment","Le routeur"]'::jsonb, 0, 'Le serveur ne fait que répondre aux requêtes reçues.', 1),
    ('bb90aab3-e4b4-552c-97a3-487eafc9615c'::uuid, '4e6885ca-c814-5e95-bcd3-7d3068cc5f88'::uuid, 'Quelle méthode HTTP place ses paramètres dans l’URL ?', 'mcq', '["GET","POST","HEAD","DELETE"]'::jsonb, 0, 'Ils sont donc visibles, historisés et mis en cache.', 2),
    ('3373274b-71e8-53b9-a197-03ce43f1632c'::uuid, '4e6885ca-c814-5e95-bcd3-7d3068cc5f88'::uuid, 'Pourquoi ne faut-il pas envoyer un mot de passe par la méthode GET ?', 'mcq', '["Il apparaîtrait dans l’URL, l’historique et les journaux du serveur","GET est plus lent","GET ne supporte pas le texte","GET est obsolète"]'::jsonb, 0, 'POST place les données dans le corps de la requête.', 3),
    ('2398e26b-8f81-5290-9005-422f1bac5067'::uuid, '4e6885ca-c814-5e95-bcd3-7d3068cc5f88'::uuid, 'Que signifie un code de statut 404 ?', 'mcq', '["La ressource demandée est introuvable","L’accès est interdit","Le serveur a échoué","La requête a réussi"]'::jsonb, 0, 'Un 403 signale un accès interdit, un 500 une erreur du serveur.', 4),
    ('fbf792fa-0515-5291-8798-bec90b2c427f'::uuid, '4e6885ca-c814-5e95-bcd3-7d3068cc5f88'::uuid, 'HTTP est un protocole avec état : le serveur se souvient du client.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est SANS état ; ce sont les cookies qui rétablissent une continuité.', 5),
    ('2682bb58-ad02-5f9b-80c7-5e4c4c1a8ff8'::uuid, '4e6885ca-c814-5e95-bcd3-7d3068cc5f88'::uuid, 'À quoi sert un cookie ?', 'mcq', '["À reconnaître un visiteur d’une requête à l’autre","À accélérer le chargement des images","À chiffrer la connexion","À router les paquets"]'::jsonb, 0, 'C’est ce qui permet de rester connecté — et ce qui permet le pistage.', 6),
    ('c95e4783-a5c2-52b3-8cd8-023ee673eb07'::uuid, '4e6885ca-c814-5e95-bcd3-7d3068cc5f88'::uuid, 'Le cadenas HTTPS garantit-il l’honnêteté d’un site ?', 'mcq', '["Non, seulement la confidentialité et l’identité du serveur","Oui, il atteste du sérieux du site","Oui, il garantit l’exactitude du contenu","Non, il ne garantit rien du tout"]'::jsonb, 0, 'Un site frauduleux peut parfaitement présenter un certificat valide.', 7),
    ('1b978ced-3e02-5251-9c74-0da1569591d9'::uuid, '4e6885ca-c814-5e95-bcd3-7d3068cc5f88'::uuid, 'Afficher une page web ne demande qu’une seule requête HTTP.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Chaque style, script et image fait l’objet d’une requête supplémentaire.', 8),
    ('50477a18-2ed7-5a04-8f2b-e0aae6f50601'::uuid, '3af13b78-52e6-5a4b-ba7a-3fa73d3cb77e'::uuid, 'Quel langage décrit la structure d’une page web ?', 'mcq', '["HTML","CSS","JavaScript","HTTP"]'::jsonb, 0, 'CSS gère la présentation, JavaScript le comportement.', 1),
    ('b6dd566e-9d8e-5732-bcd6-9ffecfdd9761'::uuid, '3af13b78-52e6-5a4b-ba7a-3fa73d3cb77e'::uuid, 'Qu’est-ce que le DOM ?', 'mcq', '["La représentation de la page en arbre d’objets, manipulable par JavaScript","Un protocole réseau","Un langage de style","Un serveur web"]'::jsonb, 0, 'C’est sur lui qu’agit tout script d’interactivité.', 2),
    ('5efe8166-f81a-5584-a0a9-1c8647e5f387'::uuid, '3af13b78-52e6-5a4b-ba7a-3fa73d3cb77e'::uuid, 'Une validation de formulaire côté client suffit à sécuriser une application.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le code client est modifiable : toute donnée doit être revérifiée côté serveur.', 3),
    ('e712148c-0b65-583f-83f7-b1711c50173d'::uuid, '3af13b78-52e6-5a4b-ba7a-3fa73d3cb77e'::uuid, 'Où s’exécute le code JavaScript d’une page ?', 'mcq', '["Dans le navigateur du visiteur","Sur le serveur web","Dans la base de données","Sur le routeur"]'::jsonb, 0, 'Il est donc lisible, modifiable et désactivable par le visiteur.', 4),
    ('5b8c1964-e153-5820-ba8a-b7c9bc47f596'::uuid, '3af13b78-52e6-5a4b-ba7a-3fa73d3cb77e'::uuid, 'Qu’est-ce qu’un gestionnaire d’événement ?', 'mcq', '["Une fonction appelée quand une action détectable se produit","Un serveur qui trie les requêtes","Une balise HTML","Une règle CSS"]'::jsonb, 0, 'Clic, saisie, envoi de formulaire : c’est le cœur de l’interactivité.', 5),
    ('577de3ad-200b-5945-a86d-de2b2c2e9ad6'::uuid, '3af13b78-52e6-5a4b-ba7a-3fa73d3cb77e'::uuid, 'Pourquoi séparer structure, présentation et comportement ?', 'mcq', '["Pour changer l’apparence sans toucher au contenu et préserver l’accessibilité","Pour accélérer le réseau","Parce que les navigateurs l’imposent","Pour réduire le nombre de fichiers"]'::jsonb, 0, 'Les lecteurs d’écran s’appuient sur la structure HTML.', 6),
    ('f1915a12-2eed-529b-80d3-e93dcd3778de'::uuid, '3af13b78-52e6-5a4b-ba7a-3fa73d3cb77e'::uuid, 'À quoi sert l’attribut « name » d’un champ de formulaire ?', 'mcq', '["Il devient la clé sous laquelle le serveur lira la valeur","Il affiche une étiquette à l’écran","Il valide le contenu","Il chiffre la donnée"]'::jsonb, 0, 'Sans lui, le champ n’est pas transmis.', 7),
    ('59a1e403-8427-5d00-a4db-9858178d789c'::uuid, '3af13b78-52e6-5a4b-ba7a-3fa73d3cb77e'::uuid, 'Le code côté serveur est accessible au visiteur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seul le résultat lui parvient ; c’est pourquoi les vérifications s’y font.', 8),
    ('91d7298f-36a5-5e50-9e11-94d3dcb70cd6'::uuid, '381a8777-8585-5774-a967-6b59af7b8298'::uuid, 'Quelle est la différence entre le simple et le double signe égal ?', 'mcq', '["Le simple affecte une valeur, le double compare","Le simple compare, le double affecte","Ils sont équivalents","Le double sert à la division"]'::jsonb, 0, 'C’est l’erreur d’entrée en programmation.', 1),
    ('0a8c369e-5d1d-5d1b-951b-f74cafd46bbe'::uuid, '381a8777-8585-5774-a967-6b59af7b8298'::uuid, 'Le typage de Python est dynamique et fort. Que signifie « fort » ?', 'mcq', '["Une opération entre types incompatibles provoque une erreur, sans conversion silencieuse","Les types ne peuvent jamais changer","Les variables doivent être déclarées","Les types sont vérifiés à la compilation"]'::jsonb, 0, 'Additionner un entier et une chaîne échoue au lieu de deviner.', 2),
    ('87c982c6-7c89-5228-abed-f23a6ddcc033'::uuid, '381a8777-8585-5774-a967-6b59af7b8298'::uuid, 'Une liste Python est modifiable en place.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Contrairement au tuple et à la chaîne, qui ne le sont pas.', 3),
    ('2845d9c9-5509-57a5-bb42-165cccbb74c7'::uuid, '381a8777-8585-5774-a967-6b59af7b8298'::uuid, 'Que se passe-t-il si deux variables désignent la même liste ?', 'mcq', '["Modifier l’une modifie l’autre","Chacune a sa propre copie","Python lève une erreur","La seconde devient un tuple"]'::jsonb, 0, 'Une variable désigne un objet, non une copie de cet objet.', 4),
    ('6a5f3eac-8425-54dd-a1ac-1127d5f7f0de'::uuid, '381a8777-8585-5774-a967-6b59af7b8298'::uuid, 'Quel type de nombre est approché en machine ?', 'mcq', '["Le flottant","L’entier","Le booléen","La chaîne"]'::jsonb, 0, 'En Python, les entiers sont exacts et sans limite de taille.', 5),
    ('744b1256-d0a8-5735-9b9d-a101904fb8d9'::uuid, '381a8777-8585-5774-a967-6b59af7b8298'::uuid, 'Qu’est-ce que le paradigme fonctionnel ?', 'mcq', '["Des fonctions sans effet de bord, dont le résultat ne dépend que des arguments","Des objets réunissant données et traitements","Une suite d’instructions modifiant un état","Un langage compilé"]'::jsonb, 0, 'La plupart des langages usuels mélangent plusieurs paradigmes.', 6),
    ('05bf0707-5edd-5a0f-a9c4-0cc8cb02596d'::uuid, '381a8777-8585-5774-a967-6b59af7b8298'::uuid, 'Sur quels critères choisit-on un langage pour un projet ?', 'mcq', '["Bibliothèques disponibles, lisibilité pour l’équipe, contraintes de performance","La date de création du langage","Le nombre de mots-clés","La couleur de son logo"]'::jsonb, 0, 'Ce n’est pas une question de goût personnel.', 7),
    ('146c55f2-bd79-5ddd-8989-78af8807f052'::uuid, '381a8777-8585-5774-a967-6b59af7b8298'::uuid, 'La syntaxe d’un langage dit ce que signifie un programme.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La syntaxe dit ce qui est bien écrit ; c’est la SÉMANTIQUE qui dit le sens.', 8),
    ('26e454de-fbc8-580a-bf2a-9c596168d438'::uuid, 'cc2e8fb8-39f2-5e30-aa16-fde332271b41'::uuid, 'Quelle est la différence entre un paramètre et un argument ?', 'mcq', '["Le paramètre est le nom dans la définition, l’argument la valeur passée à l’appel","Ce sont deux synonymes","Le paramètre est toujours un entier","L’argument est le résultat de la fonction"]'::jsonb, 0, 'Distinction classique, souvent demandée.', 1),
    ('49add9b2-da8b-5707-9aac-d96286bc011a'::uuid, 'cc2e8fb8-39f2-5e30-aa16-fde332271b41'::uuid, 'Pourquoi vaut-il mieux retourner une valeur que l’afficher ?', 'mcq', '["Parce qu’une valeur affichée n’est plus disponible pour un autre calcul","Parce que l’affichage est plus lent","Parce que Python l’interdit","Parce que cela consomme de la mémoire"]'::jsonb, 0, 'Une fonction qui affiche ne se réutilise pas.', 2),
    ('bc3f231c-0cfa-5bb5-bc57-b86adc244e8f'::uuid, 'cc2e8fb8-39f2-5e30-aa16-fde332271b41'::uuid, 'Une variable définie dans une fonction est visible à l’extérieur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est LOCALE : elle n’existe que pendant l’exécution de la fonction.', 3),
    ('9b90e777-bf9d-56ae-a782-b6c21ff42c8b'::uuid, 'cc2e8fb8-39f2-5e30-aa16-fde332271b41'::uuid, 'Qu’est-ce qu’un effet de bord ?', 'mcq', '["Une modification autre que la valeur de retour","Une erreur d’exécution","Un retour de plusieurs valeurs","Un appel récursif"]'::jsonb, 0, 'Permis, mais il doit être voulu et documenté.', 4),
    ('929f6f73-166c-5e39-9087-787f2ef66aa8'::uuid, 'cc2e8fb8-39f2-5e30-aa16-fde332271b41'::uuid, 'Que contient une spécification complète de fonction ?', 'mcq', '["Ce qu’elle fait, ce qu’elle reçoit, ce qu’elle rend, ce qui est garanti en sortie","Le nom de son auteur et la date","Le nombre de lignes de code","La liste des variables globales"]'::jsonb, 0, 'Préconditions et postconditions en font partie.', 5),
    ('6a0e1784-39da-565c-9b23-3559f9b79c75'::uuid, 'cc2e8fb8-39f2-5e30-aa16-fde332271b41'::uuid, 'À quoi sert une assertion ?', 'mcq', '["À vérifier une condition et arrêter le programme au bon endroit si elle est fausse","À afficher une valeur","À accélérer l’exécution","À documenter le code"]'::jsonb, 0, 'Mieux vaut échouer tôt que produire un résultat faux dix étapes plus loin.', 6),
    ('3bd63ab8-b30f-54a4-8f18-0a513c670f77'::uuid, 'cc2e8fb8-39f2-5e30-aa16-fde332271b41'::uuid, 'Pourquoi éviter les variables globales ?', 'mcq', '["Elles créent des dépendances invisibles entre parties du programme","Elles ralentissent l’exécution","Python les interdit","Elles occupent trop de mémoire"]'::jsonb, 0, 'Une fonction doit recevoir par ses paramètres et rendre par son retour.', 7),
    ('095da55e-fc7b-5f9c-9134-cd772eade5c9'::uuid, 'cc2e8fb8-39f2-5e30-aa16-fde332271b41'::uuid, 'En Python, une fonction sans instruction de retour rend la valeur None.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est une source d’erreurs quand on oublie le retour.', 8),
    ('52d2a0f5-4224-5d29-97f1-1d409498c14b'::uuid, 'd3f02505-686c-580a-8a93-d86338693e90'::uuid, 'Que montre un jeu de tests réussi ?', 'mcq', '["Rien sur l’absence de bugs : il montre seulement leur présence quand il échoue","Que le programme est prouvé correct","Que le programme est optimal","Que le code est lisible"]'::jsonb, 0, 'Passer cent tests n’empêche pas d’échouer au cent-unième.', 1),
    ('5937ab7f-02f6-5c5d-be7a-00ca1e00bc42'::uuid, 'd3f02505-686c-580a-8a93-d86338693e90'::uuid, 'Quels cas de test trouvent le plus de bugs ?', 'mcq', '["Les cas limites","Les cas courants","Les cas les plus longs","Les cas aléatoires"]'::jsonb, 0, 'Le cas courant, on l’avait en tête en écrivant le code.', 2),
    ('0c97f864-17ee-559e-ba0d-e932663a0010'::uuid, 'd3f02505-686c-580a-8a93-d86338693e90'::uuid, 'Qu’est-ce qu’une régression ?', 'mcq', '["Un bug réintroduit dans du code qui fonctionnait","Une baisse de performance","Un retour à une version antérieure","Une erreur de compilation"]'::jsonb, 0, 'Rejouer les tests à chaque modification sert à la détecter.', 3),
    ('353cf134-6c66-5e97-853a-1faf84dadcb5'::uuid, 'd3f02505-686c-580a-8a93-d86338693e90'::uuid, 'Qu’est-ce qu’un variant de boucle ?', 'mcq', '["Une quantité entière positive qui décroît strictement, prouvant la terminaison","Une propriété vraie à chaque tour","Une variable modifiée dans la boucle","Un compteur d’itérations"]'::jsonb, 0, 'L’invariant, lui, sert à prouver la correction.', 4),
    ('b11d32bf-f3d9-5672-8cd3-e40a072bb202'::uuid, 'd3f02505-686c-580a-8a93-d86338693e90'::uuid, 'Quelle est la première étape du débogage ?', 'mcq', '["Reproduire l’erreur de façon fiable, sur la plus petite entrée possible","Corriger la ligne suspecte","Réécrire la fonction","Ajouter des commentaires"]'::jsonb, 0, 'Corriger au hasard déplace le bug plus qu’il ne le supprime.', 5),
    ('e2d5850e-3d20-5b1a-a5f8-d8a7d5af14f9'::uuid, 'd3f02505-686c-580a-8a93-d86338693e90'::uuid, 'Que faut-il faire après avoir corrigé un bug ?', 'mcq', '["Ajouter un test qui échouait avant la correction","Supprimer les anciens tests","Recompiler le projet","Changer de langage"]'::jsonb, 0, 'C’est ce qui empêche le bug de revenir.', 6),
    ('0f643da4-1ebd-5fde-9c17-95d2406cb6be'::uuid, 'd3f02505-686c-580a-8a93-d86338693e90'::uuid, 'Un commentaire doit expliquer ce que fait la ligne de code.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il doit expliquer POURQUOI : le « quoi » se lit déjà dans le code.', 7),
    ('bddaf8ca-4f12-5e8e-bcc1-551414646e3f'::uuid, 'd3f02505-686c-580a-8a93-d86338693e90'::uuid, 'À quoi sert un système de gestion de versions ?', 'mcq', '["À conserver l’historique, revenir en arrière et travailler à plusieurs","À accélérer l’exécution","À compiler le code","À tester automatiquement"]'::jsonb, 0, 'C’est l’outil de base du travail en équipe.', 8),
    ('b8aa89e3-ad30-5a28-8db1-946d9b371147'::uuid, 'c5cfb027-b162-50c1-bd50-2f30fad708cd'::uuid, 'Qu’est-ce qu’un variant de boucle ?', 'mcq', '["Une quantité entière positive qui décroît strictement à chaque tour","Une propriété vraie à chaque tour","Une variable modifiée dans la boucle","Le nombre total d’itérations"]'::jsonb, 0, 'Il prouve la TERMINAISON ; l’invariant prouve la correction.', 1),
    ('fd4bdbfb-f9f4-5141-ad07-845cc861a4b0'::uuid, 'c5cfb027-b162-50c1-bd50-2f30fad708cd'::uuid, 'Quelle est la complexité d’une recherche dichotomique dans un tableau trié ?', 'mcq', '["Logarithmique","Linéaire","Quadratique","Constante"]'::jsonb, 0, 'Chaque comparaison élimine la moitié des candidats.', 2),
    ('50fa6065-c090-5417-b8cf-48005fc0404f'::uuid, 'c5cfb027-b162-50c1-bd50-2f30fad708cd'::uuid, 'Un algorithme qui termine rend nécessairement un résultat correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Terminaison et correction sont deux propriétés indépendantes.', 3),
    ('6a140c68-33ff-5422-8422-259099e4e147'::uuid, 'c5cfb027-b162-50c1-bd50-2f30fad708cd'::uuid, 'Quelle est la complexité de deux boucles imbriquées parcourant chacune n éléments ?', 'mcq', '["Quadratique","Linéaire","Logarithmique","n log n"]'::jsonb, 0, 'C’est celle du tri par sélection ou par insertion.', 4),
    ('81398261-fbaa-5940-88b3-af378a970187'::uuid, 'c5cfb027-b162-50c1-bd50-2f30fad708cd'::uuid, 'Pourquoi raisonne-t-on d’ordinaire sur le pire cas ?', 'mcq', '["Parce que c’est la seule garantie sur laquelle dimensionner un système","Parce qu’il est plus simple à calculer","Parce qu’il se produit le plus souvent","Parce que le meilleur cas est imprévisible"]'::jsonb, 0, 'Le meilleur cas ne dit rien de ce qu’on peut promettre.', 5),
    ('f20f19a0-72af-5e65-a080-9ca70fa75f61'::uuid, 'c5cfb027-b162-50c1-bd50-2f30fad708cd'::uuid, 'Combien d’opérations un algorithme quadratique effectue-t-il sur un million d’éléments ?', 'mcq', '["Environ mille milliards","Environ un million","Environ deux millions","Environ mille"]'::jsonb, 0, 'Le linéaire en ferait un million : d’où l’écart entre une seconde et des semaines.', 6),
    ('0792bf5a-bb1a-54af-9bc8-7478277f6d9d'::uuid, 'c5cfb027-b162-50c1-bd50-2f30fad708cd'::uuid, 'Dans un calcul de complexité, on garde les constantes multiplicatives.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On ne retient que l’ordre de grandeur quand n devient grand.', 7),
    ('d360c230-6edb-5bb6-80e9-1fbfbb77fca4'::uuid, 'c5cfb027-b162-50c1-bd50-2f30fad708cd'::uuid, 'Que prouve un invariant de boucle ?', 'mcq', '["La correction de l’algorithme","Sa terminaison","Sa complexité","Sa lisibilité"]'::jsonb, 0, 'Il est vrai avant la boucle et conservé par chaque tour.', 8),
    ('3e85385a-bb8d-50d0-a769-db986411a9ea'::uuid, 'da4b8338-d02f-57e3-93f3-cecd8e941285'::uuid, 'Quel est l’indice du premier élément d’une liste Python ?', 'mcq', '["0","1","−1","Cela dépend de la liste"]'::jsonb, 0, 'Le dernier est d’indice n − 1.', 1),
    ('f3d7ba54-c36c-5ebd-a6b3-f2e74ba98f2d'::uuid, 'da4b8338-d02f-57e3-93f3-cecd8e941285'::uuid, 'Quel est le coût d’un accès à la case d’indice i d’un tableau ?', 'mcq', '["Constant","Linéaire","Logarithmique","Quadratique"]'::jsonb, 0, 'Il ne dépend pas de la taille du tableau.', 2),
    ('140f75d6-d80d-518c-a8df-8c51bfb9a4fc'::uuid, 'da4b8338-d02f-57e3-93f3-cecd8e941285'::uuid, 'Que provoque une boucle allant « jusqu’à n » sur un tableau de n éléments ?', 'mcq', '["Une erreur d’indice hors bornes","Un résultat correct","Une boucle infinie","Une copie du tableau"]'::jsonb, 0, 'Le dernier indice valide est n − 1.', 3),
    ('b8592291-99b0-582d-9e25-a45d3ffade14'::uuid, 'da4b8338-d02f-57e3-93f3-cecd8e941285'::uuid, 'Créer une matrice en multipliant une liste par un entier est une méthode sûre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On obtient n références vers la MÊME ligne : modifier une case en modifie une par ligne.', 4),
    ('1c04c1d6-4b0b-5e22-9a96-9b9f159657d2'::uuid, 'da4b8338-d02f-57e3-93f3-cecd8e941285'::uuid, 'Quel est le coût du parcours complet d’une matrice carrée de côté n ?', 'mcq', '["Quadratique","Linéaire","Constant","Logarithmique"]'::jsonb, 0, 'Deux boucles imbriquées de n tours chacune.', 5),
    ('58c1f371-4d9a-5a78-9cd6-ca1de7fa6017'::uuid, 'da4b8338-d02f-57e3-93f3-cecd8e941285'::uuid, 'Quand faut-il parcourir un tableau par indice plutôt que par élément ?', 'mcq', '["Quand on veut modifier le tableau ou comparer un élément à son voisin","Toujours","Jamais","Uniquement pour les matrices"]'::jsonb, 0, 'Le parcours par élément suffit quand la position n’importe pas.', 6),
    ('6ba7f884-0a19-5c99-bd0f-125996848108'::uuid, 'da4b8338-d02f-57e3-93f3-cecd8e941285'::uuid, 'Une affectation entre deux variables de type liste crée une copie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les deux noms désignent le même objet ; le tranchage, lui, copie.', 7),
    ('10aa92af-5e74-5a87-bd21-389804abd5ef'::uuid, 'da4b8338-d02f-57e3-93f3-cecd8e941285'::uuid, 'Comment accède-t-on à un élément d’une matrice ?', 'mcq', '["Par deux indices : ligne puis colonne","Par un seul indice","Par son nom","Par une clé"]'::jsonb, 0, 'Une matrice est une liste de listes.', 8),
    ('f6176df2-b58b-5c4a-b2bf-208e6995042f'::uuid, 'c032e692-bf5f-5cdf-b5d0-08dc06fd5d2a'::uuid, 'Quelle condition la recherche dichotomique exige-t-elle ?', 'mcq', '["Que le tableau soit trié","Que le tableau soit de taille paire","Que les éléments soient uniques","Aucune condition"]'::jsonb, 0, 'Sur un tableau non trié, elle rend un résultat faux sans le signaler.', 1),
    ('0a29de07-4569-5712-87f3-a1fb9300d273'::uuid, 'c032e692-bf5f-5cdf-b5d0-08dc06fd5d2a'::uuid, 'Quel est le coût de la recherche séquentielle dans le pire cas ?', 'mcq', '["Linéaire","Logarithmique","Constant","Quadratique"]'::jsonb, 0, 'n comparaisons quand l’élément est absent.', 2),
    ('175c6cee-55b0-5a32-a86f-43b66c301ce6'::uuid, 'c032e692-bf5f-5cdf-b5d0-08dc06fd5d2a'::uuid, 'Combien de comparaisons environ pour une dichotomie sur un million d’éléments ?', 'mcq', '["Une vingtaine","Un million","Mille","Cent mille"]'::jsonb, 0, 'Chaque comparaison élimine la moitié des candidats.', 3),
    ('7b0b676d-0c59-5ea3-a875-ef9d266763c0'::uuid, 'c032e692-bf5f-5cdf-b5d0-08dc06fd5d2a'::uuid, 'Quel est le variant de boucle de la recherche dichotomique ?', 'mcq', '["La taille de l’intervalle de recherche, divisée par deux à chaque tour","L’indice courant","Le nombre d’éléments trouvés","La valeur cherchée"]'::jsonb, 0, 'Une quantité entière positive strictement décroissante.', 4),
    ('2f450d3c-cd4d-518f-bc3c-79e0d2b01bc7'::uuid, 'c032e692-bf5f-5cdf-b5d0-08dc06fd5d2a'::uuid, 'Le tri par insertion et le tri par sélection sont tous deux quadratiques dans le pire cas.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Mais l’insertion est bien meilleure sur un tableau presque trié.', 5),
    ('7b4d5d48-4800-5573-bdb8-fbaf7e1f9ca0'::uuid, 'c032e692-bf5f-5cdf-b5d0-08dc06fd5d2a'::uuid, 'Comment trouver le maximum d’un tableau ?', 'mcq', '["En mémorisant un candidat et en le remplaçant dès qu’on trouve mieux","En triant d’abord le tableau","Par recherche dichotomique","En comparant tous les couples d’éléments"]'::jsonb, 0, 'Un seul parcours linéaire suffit.', 6),
    ('b028e361-b539-5983-91f4-b5e0f2e4e343'::uuid, 'c032e692-bf5f-5cdf-b5d0-08dc06fd5d2a'::uuid, 'Quelle est la complexité des tris employés par les bibliothèques standard ?', 'mcq', '["n log n","Quadratique","Linéaire","Exponentielle"]'::jsonb, 0, 'Sur un million d’éléments, l’écart avec n² sépare la seconde de plusieurs jours.', 7),
    ('d697d096-3b51-56f5-9ca8-1baae152acfa'::uuid, 'c032e692-bf5f-5cdf-b5d0-08dc06fd5d2a'::uuid, 'Le tri par sélection place à chaque tour un élément à sa position définitive.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il cherche le minimum du reste et l’échange avec la première case non triée.', 8),
    ('d6b5a193-b10a-5209-aa7d-39f3cf5c0c47'::uuid, 'bd3a9a63-638d-523f-a805-c4444923a696'::uuid, 'Que représente une colonne dans une table de données ?', 'mcq', '["Un descripteur, c’est-à-dire un attribut","Un enregistrement","Une clé primaire","Un fichier"]'::jsonb, 0, 'Chaque ligne est un enregistrement.', 1),
    ('d46b2e7b-8ca4-59e2-97dd-119699f89930'::uuid, 'bd3a9a63-638d-523f-a805-c4444923a696'::uuid, 'Quelle représentation en mémoire est la plus lisible pour une table ?', 'mcq', '["Une liste de dictionnaires","Une liste de listes","Une chaîne de caractères","Un tuple d’entiers"]'::jsonb, 0, 'On accède aux valeurs par le nom du descripteur, pas par un numéro.', 2),
    ('c1a0360e-987e-5c73-9558-23400f7327bb'::uuid, 'bd3a9a63-638d-523f-a805-c4444923a696'::uuid, 'Un fichier CSV est un format binaire propriétaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un format TEXTE, lisible par n’importe quel outil.', 3),
    ('1f9163e8-2c25-5bf6-af98-4751eb3b5101'::uuid, 'bd3a9a63-638d-523f-a805-c4444923a696'::uuid, 'Quels sont les trois traitements de base sur une table ?', 'mcq', '["Rechercher, trier, agréger","Créer, modifier, supprimer","Lire, écrire, fermer","Compresser, chiffrer, envoyer"]'::jsonb, 0, 'L’agrégation peut se faire par groupe.', 4),
    ('3e46201d-5431-5887-950e-58c4f629941b'::uuid, 'bd3a9a63-638d-523f-a805-c4444923a696'::uuid, 'Que doit garantir une clé de fusion entre deux tables ?', 'mcq', '["Qu’elle identifie de façon unique un enregistrement","Qu’elle soit un nombre","Qu’elle soit triée","Qu’elle soit la première colonne"]'::jsonb, 0, 'Sinon la fusion produit des doublons silencieux.', 5),
    ('0444f38b-cbbf-5e16-b267-45a76fbee673'::uuid, 'bd3a9a63-638d-523f-a805-c4444923a696'::uuid, 'Quel piège guette la lecture d’un fichier CSV ?', 'mcq', '["Un séparateur présent dans une valeur, ou un encodage mal deviné","Un fichier trop court","L’absence de titre","Un nombre pair de colonnes"]'::jsonb, 0, 'La virgule décimale prise pour un séparateur en est un cas classique.', 6),
    ('5baac76a-cbca-5609-8c7c-9a7eecc8da7b'::uuid, 'bd3a9a63-638d-523f-a805-c4444923a696'::uuid, 'Que représente la première ligne d’un fichier CSV, d’ordinaire ?', 'mcq', '["Les noms des descripteurs","Le premier enregistrement","La taille du fichier","La date de création"]'::jsonb, 0, 'C’est une convention, pas une obligation du format.', 7),
    ('1ef8cf80-8035-55e1-b4cb-f4e3aa199767'::uuid, 'bd3a9a63-638d-523f-a805-c4444923a696'::uuid, 'Le nettoyage des données influence le résultat de l’analyse et doit être documenté.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Valeurs manquantes, doublons et formats mélangés appellent des décisions explicites.', 8),
    ('4fb4dacf-5221-558b-8017-5a8f5d94c15d'::uuid, '059222c8-068f-5042-ab33-c4cf85a83348'::uuid, 'Qu’est-ce qu’un algorithme glouton ?', 'mcq', '["Un algorithme qui fait à chaque étape le meilleur choix immédiat, sans revenir en arrière","Un algorithme qui explore toutes les solutions","Un algorithme récursif","Un algorithme qui consomme beaucoup de mémoire"]'::jsonb, 0, 'Rapide et simple, mais rarement garanti optimal.', 1),
    ('9c9ad1e9-8f34-5690-97ad-34ade524b702'::uuid, '059222c8-068f-5042-ab33-c4cf85a83348'::uuid, 'Un algorithme glouton donne-t-il toujours la solution optimale ?', 'mcq', '["Non, seulement dans certains problèmes","Oui, toujours","Oui, si les données sont triées","Non, jamais"]'::jsonb, 0, 'Il donne toujours UNE solution, pas nécessairement la meilleure.', 2),
    ('cdc9cd2b-2a63-5a6c-bb1e-edb95950bf76'::uuid, '059222c8-068f-5042-ab33-c4cf85a83348'::uuid, 'Avec des pièces de 1, 3 et 4, combien de pièces le glouton rend-il pour 6 ?', 'mcq', '["Trois : 4 + 1 + 1","Deux : 3 + 3","Six pièces de 1","Quatre"]'::jsonb, 0, 'L’optimum était 3 + 3 : le glouton échoue sur ce système.', 3),
    ('43d84fc6-cd06-58f3-8e34-a92147ed2a3b'::uuid, '059222c8-068f-5042-ab33-c4cf85a83348'::uuid, 'Que le glouton fonctionne pour le rendu de monnaie en euros est une propriété…', 'mcq', '["du système de pièces, pas de l’algorithme","de l’algorithme lui-même","de la monnaie électronique","du hasard"]'::jsonb, 0, 'Un autre système de pièces le met en défaut.', 4),
    ('008b597a-af52-5bd0-9cf9-4ebf9b44f1e0'::uuid, '059222c8-068f-5042-ab33-c4cf85a83348'::uuid, 'Quel critère glouton donne un bon résultat au problème du sac à dos ?', 'mcq', '["Le rapport valeur sur poids","Le poids le plus faible","La valeur la plus élevée","L’ordre d’arrivée"]'::jsonb, 0, 'Excellent en général, mais non optimal.', 5),
    ('2863144e-1731-5e16-843f-8ef2823dce68'::uuid, '059222c8-068f-5042-ab33-c4cf85a83348'::uuid, 'L’algorithme de Dijkstra est glouton et optimal si les poids sont positifs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un cas où la structure du problème garantit l’optimalité.', 6),
    ('5b62f68f-a5c0-5c01-8d7e-439dd96e5750'::uuid, '059222c8-068f-5042-ab33-c4cf85a83348'::uuid, 'Quelle est la complexité typique d’un glouton après un tri préalable ?', 'mcq', '["n log n","Quadratique","Exponentielle","Constante"]'::jsonb, 0, 'Le tri domine, le parcours qui suit est linéaire.', 7),
    ('6fd0e741-bfee-52ef-a2c2-d999b5d7c11e'::uuid, '059222c8-068f-5042-ab33-c4cf85a83348'::uuid, 'Quand faut-il préférer une méthode exacte à un glouton ?', 'mcq', '["Quand l’optimalité est exigée et que la structure ne la garantit pas","Quand les données sont nombreuses","Quand le temps de calcul est limité","Toujours"]'::jsonb, 0, 'Son coût sera bien plus élevé : c’est un arbitrage.', 8),
    ('c3156d5a-8935-5935-b264-ff7302e41ecd'::uuid, '29426197-2e10-50e5-9964-033fff22ebe0'::uuid, 'Quelle est la différence entre apprentissage supervisé et non supervisé ?', 'mcq', '["Le supervisé part d’exemples étiquetés, le non supervisé de données sans étiquette","Le supervisé est plus rapide","Le non supervisé exige plus de données","Le supervisé ne fait que de la régression"]'::jsonb, 0, 'Le non supervisé cherche une structure, comme un partitionnement.', 1),
    ('7be78f30-3287-5b9c-8420-0b347e9fccb1'::uuid, '29426197-2e10-50e5-9964-033fff22ebe0'::uuid, 'Comment l’algorithme des k plus proches voisins classe-t-il un point nouveau ?', 'mcq', '["Par la classe majoritaire parmi ses k voisins les plus proches","Par la classe de son voisin le plus lointain","Par tirage aléatoire","Par la moyenne de toutes les classes"]'::jsonb, 0, 'Aucun entraînement : tout le travail se fait à la prédiction.', 2),
    ('6dbe0d99-f2d0-57e3-bf33-6f420a7b28da'::uuid, '29426197-2e10-50e5-9964-033fff22ebe0'::uuid, 'Pourquoi faut-il normaliser les descripteurs avant un calcul de distance ?', 'mcq', '["Sinon une variable de grande amplitude écrase les autres","Pour accélérer le calcul","Pour éviter les valeurs manquantes","Pour équilibrer les classes"]'::jsonb, 0, 'Une variable en milliers dominerait une variable entre 0 et 1.', 3),
    ('902ebc46-6c7f-5b0e-bab4-b38fa776fcbb'::uuid, '29426197-2e10-50e5-9964-033fff22ebe0'::uuid, 'Qu’est-ce que le surapprentissage ?', 'mcq', '["Un modèle qui a retenu ses exemples au lieu d’en tirer une règle générale","Un modèle entraîné trop longtemps sur peu de données seulement","Un modèle trop rapide","Un modèle mal normalisé"]'::jsonb, 0, 'Il donne d’excellents résultats sur ses données et de mauvais sur les nouvelles.', 4),
    ('cb3c974b-3f7d-5f76-9b46-686a2b2bacd8'::uuid, '29426197-2e10-50e5-9964-033fff22ebe0'::uuid, 'Sur quelles données faut-il évaluer un modèle ?', 'mcq', '["Sur des données jamais vues pendant l’apprentissage","Sur les données d’apprentissage","Sur toutes les données disponibles","Sur des données générées au hasard"]'::jsonb, 0, 'D’où la séparation en ensemble d’apprentissage et ensemble de test.', 5),
    ('7d23e13f-92bf-59d3-b1d1-4cf554d47e79'::uuid, '29426197-2e10-50e5-9964-033fff22ebe0'::uuid, 'Un modèle entraîné sur des données biaisées produit des prédictions neutres.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il reproduit les biais, en leur donnant l’apparence de l’objectivité.', 6),
    ('3e890ad3-e053-51e5-aedd-86b3e7144da2'::uuid, '29426197-2e10-50e5-9964-033fff22ebe0'::uuid, 'Quel est le coût de la prédiction avec les k plus proches voisins ?', 'mcq', '["Linéaire en le nombre d’exemples, pour chaque point à classer","Constant","Logarithmique","Nul, tout est calculé à l’entraînement"]'::jsonb, 0, 'C’est le prix de l’absence de phase d’entraînement.', 7),
    ('7687bea4-ac72-5dbd-8980-bada094c0c79'::uuid, '29426197-2e10-50e5-9964-033fff22ebe0'::uuid, 'Que se passe-t-il si k est choisi trop grand ?', 'mcq', '["Les frontières entre classes sont lissées jusqu’à s’effacer","La prédiction suit le bruit","Le calcul devient impossible","Le modèle refuse de prédire"]'::jsonb, 0, 'Un k trop petit, à l’inverse, rend le modèle sensible au bruit.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('nsi');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('nsi')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 273 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 273 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
